CREATE TABLE IF NOT EXISTS vacancies (id TEXT PRIMARY KEY, title TEXT NOT NULL, employer TEXT NOT NULL, sector TEXT NOT NULL CHECK(sector IN ('government','private','military')), description TEXT NOT NULL, salary INTEGER NOT NULL CHECK(salary>=0), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS job_applications (id TEXT PRIMARY KEY, vacancy_id TEXT NOT NULL REFERENCES vacancies(id), applicant_id TEXT NOT NULL REFERENCES users(id), statement TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','reviewing','accepted','rejected')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(vacancy_id,applicant_id));
CREATE INDEX IF NOT EXISTS idx_job_applications_vacancy ON job_applications(vacancy_id);
CREATE INDEX IF NOT EXISTS idx_job_applications_applicant ON job_applications(applicant_id);
